/// <summary>
/// createPurchTable method and return PurchId
/// </summary>
/// <param name = "_reqTrans">ReqTrans</param>
/// <param name = "_reqPO">ReqPo</param>
/// <param name = "_agreementId">PurchAgreementId</param>
/// <param name = "_projId">ProjId</param>
/// <param name = "_salesId">SalesId</param>
/// <returns>PurchId</returns>
protected PurchId createPurchTable(
    ReqTrans            _reqTrans,
    ReqPO               _reqPO,
    PurchAgreementId    _agreementId,
    ProjId              _projId,
    SalesId             _salesId)
{
    PurchId purchIdLoc;
    PurchAgreementId purchAgreementId = _agreementId;

    if(_reqPO.AVAAgreementLineRecId)
    {
        purchAgreementId = AgreementLine::find(_reqPO.AVAAgreementLineRecId).getPurchAgreementId();
    }

    purchIdLoc = next createPurchTable(_reqTrans, _reqPO, purchAgreementId, _projId, _salesId);

    return purchIdLoc;
}

/// <summary>
///     Initializes a record of type <c>InventTransferTable</c>.
/// </summary>
/// <param name = "_reqPO">
///     A record of type <c>ReqPO</c>.
/// </param>
/// <param name = "_fromInventLocationId">
///     The Id of the warehouse to transfer from.
/// </param>
/// <param name = "_toInventLocationId">
///     The Id of the warehouse to transfer to.
/// </param>
/// <returns>
///     A new <c>InventTransferTable</c> record.
/// </returns>
/// <exception cref="Exception::Error">
///     The transfer order could not be created.
/// </exception>
protected InventTransferTable initInventTransferTable(
    ReqPO            _reqPO,
    InventLocationId _fromInventLocationId,
    InventLocationId _toInventLocationId)
{
    InventTransferTable retVal;

    InventLocation      locInventLocation;

    retVal  = next initInventTransferTable( _reqPO,
                                            _fromInventLocationId,
                                            _toInventLocationId     );

    locInventLocation = InventLocation::find(_toInventLocationId);
    if(     locInventLocation.VendAccount
        &&  retVal.KCS_TransferType != KCS_TransferType::ExternalProduction)
    {
        retVal.KCS_TransferType = KCS_TransferType::ExternalProduction;
    }

    return retVal;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_reqTrans">ReqTrans</param>
/// <param name = "_reqPO">ReqPO</param>
/// <param name = "_prodBOMParent">ProdBOM</param>
/// <returns>ProdTable</returns>
protected ProdTable createProdTable(
    ReqTrans    _reqTrans,
    ReqPO       _reqPO,
    ProdBOM     _prodBOMParent)
{
    ProdTable   prodTable;
    prodTable = next createProdTable(_reqTrans, _reqPO, _prodBOMParent);
    prodTable.avaSetProdPoolFromRoute();
    return prodTable;
}
